import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第三十六章 耕种解脱的田地","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/36第三十六章 耕种解脱的田地.md","filePath":"meditation/巴利文大藏经/36第三十六章 耕种解脱的田地.md"}'),r={name:"meditation/巴利文大藏经/36第三十六章 耕种解脱的田地.md"};function _(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第三十六章-耕种解脱的田地" tabindex="-1">第三十六章 耕种解脱的田地 <a class="header-anchor" href="#第三十六章-耕种解脱的田地" aria-label="Permalink to &quot;第三十六章 耕种解脱的田地&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>2.优婆塞品</p><p>相应部7相应11经/耕田婆罗堕若经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，佛陀住在摩揭陀国一那罗的村庄中，有一天，婆罗堕若婆罗门正在让仆人赶着五百头牛犁地，播种。</p><p>那时，佛陀中午前穿好法衣，拿着饭钵，来到婆罗堕若婆罗门耕田的地方化缘饭食。到了饭点，农作的仆人们拿着盆碗打菜吃饭。婆罗堕若婆罗门看见佛陀也在排队，就走过去对佛陀说：“你是谁？你是我的仆人吗？你有农作耕田吗？在这里排队吃饭的都是干过活的人，你如果想吃这里的饭，就的去帮我耕田，你耕种田地后，就可以在这里吃饭。我们这里不提供白食，没有耕田的人，不能在这里吃饭，你听清楚了没有！”</p><p>佛陀说：“婆罗门，如来已经耕田，播种。所以可以在这里排队吃饭。”</p><p>婆罗堕若婆罗门说：“哦哟，你还是个出家人，睁眼说瞎话呀，我刚才一直在监督他们耕田播种，没有看见你的身影呀，你说你耕田播种了，你耕田播种的农具：轭、锄、犁、镵、刺棒在哪里？还有你的耕牛在哪里？你自称已经耕过田了，已经播过种了，可是我根本就没有看见你耕田播种，那么你这位辛勤的农夫，请你告诉我们，如何让我们知道你已经耕过田，播过种了？出家人！别说瞎话！我可不是被骗大的！你想在我这里骗吃骗喝，没门，我不信你们那套，我还是那句话，要吃这里的饭，就要先去耕田播种。你要么老老实实的去耕田播种，要么赶快从我面前消失，不然我就叫人收拾你了，听到没有！”</p><p>这时，婆罗门说偈言：</p><p>「汝自云农夫，我不见汝耕。</p><p>我问农夫语，何知汝耕种。」</p><p>佛陀说：“如来以清净的信心为种子。以管束好自己的行为，言语，念想不去做恶行，断恶修善，受持好戒律作为雨水。智慧是如来的耕地用的锄与犁。羞耻心，自省心是如来推动犁向前移动的犁头镵。以内心清净安定为捆绑耕牛的绳子。以内心生起正念，善念为驱赶耕牛前进的棍棒。以守护好身体行为，口说言语不做恶行，来控制胃里食物的消耗，保证耕田的体力。如来用正确的修行来割去田里的杂草，得到清净无染的解脱。持之以恒，精进的修行是如来耕作时的耐力和持久力。放下世间的一切负担，重荷，解除世间一切的束缚捆绑就是如来的耕牛。如来的内心已经不会再生起或挂念善恶的念想，不会在生起或挂念功德和罪业的念想，不会再生起或挂念世间一切的事物事情，这就是耕地农作持续平稳的运行。这样持之以恒，长久的去修行，这样持之以恒，长久的去耕地，不会再回头，不会再后退。持续的向前修行，持续的向前耕地也不会产生喜怒哀乐等等一切挂念和执着的念想。这就是如来耕作的田，用这样的方法耕田，播种，能够解除世间一切烦恼和痛苦的摧残和折磨。用这样的方法耕田，播种，能够从生死轮回的煎熬和痛苦中永远的解脱出来。用这样的方法耕田，播种，能够获得不生不灭的解脱果实。”</p><p>这时，佛陀说偈言：</p><p>「信仰是种子，锻炼是甘雨。</p><p>智慧犁为锄，惭乃为犁镵。</p><p>定为是其绳，正念我刺棒。</p><p>守身及守语，以知食之量，</p><p>正行割杂草，清净无污染。</p><p>精进乃我负，重荷立牡牛。</p><p>无着运安稳，行而无有归，</p><p>行前亦无悲，如是我耕耘，</p><p>不死是果实，以为此耕耘，</p><p>我悉脱苦恼。」</p><p>佛陀说法后，婆罗堕若婆罗门惊讶的看着佛陀说：“大德，您耕种的可不是一般的田地呀，您收获的不是一般的果实呀！请您原谅我刚才对您的无礼行为。大德，这里给仆人吃的饭菜太难吃了，请您到我的住处去吃饭，我将会为您准备好上等的饭菜，供您享用。”</p><p>佛陀说：“婆罗门，如来已经为你说法，就不应该再接受你的饮食供养，如来不是为了你的饮食供养才说法的，如来是想让你开启智慧，具足正确的修行观念。如果你执意要在如来说法后，供养如来饮食，那就是不如法的行为。因为过去的诸佛如来外出化缘饭食，如果众生没有在如来说法之前供养如来，那么如来就不会再接受众生的供养，诸佛如来随顺因缘，众生没有第一时间供养如来，说明因缘不具足，诸佛如来为众生说法为的是让他们解除烦恼和痛苦，为的是让他们开启智慧，不是为了获得供养而说法。婆罗门，你可以将这些饮食供养给其他的出家人，修行人。你不用为没有供养饮食给如来而感到自责，因为你内心中不正确的见解已经被如来除灭，你内心中由此产生出来的烦恼也已经被如来除灭，你现在已经知道如来是如何耕种田地的，已经知道如何耕种田地才能获得不生不灭解脱生死轮回的果实，你内心不正确的见解已经被如来纠正，你错误的见解已经被如来平息，除灭。受持戒律的出家人，修行人，就是世间人获得福德的田地，布施供养受持戒律的出家人，修行人就能为自己种植出很多福德和功德，而福德功德的多少决定了投生的类别，福德功德深厚的众生投生到富贵之家，上生到天界享福，甚至于从生死轮回的煎熬和痛苦中永远的解脱出来。福德薄弱，罪业深重的众生投生到贫贱之家，下堕到地狱，饿鬼，畜生三恶道受苦。因此世间的人，众生都应该尽快的为自己的现在世，未来世积聚福德功德，不要等到临死的时候才来后悔没有种植福德和功德。”</p><p>这时，佛陀说偈言：</p><p>「唱偈非为食，婆罗门有此。</p><p>知见者非法，诸佛之唱偈。</p><p>非为获供养，如来顺因缘，</p><p>说法不为利，婆罗门供养，</p><p>广施正行人，以事奉饮食，</p><p>为求功德田。」</p>',32)]))}const f=t(r,[["render",_]]);export{m as __pageData,f as default};
